				return true;
			}

			if (!thisScript.oper({
				name: '第一排第一个御魂+0',
				operator: [thisOperator[1], thisOperator[14]]
			}) && thisScript.oper({
				name: '背景墙，灰奉纳',
				operator: [thisOperator[5]]
			})) {
				const thisconf = thisScript.scheme.config['302'];
				if (thisconf && thisconf.scheme_switch_enabled) {
					thisScript.rerun(thisconf.next_scheme);
					sleep(3000);
					return;
				} else {
					thisScript.doPush(thisScript, { text: '奉纳结束或未正确使用，请查看。', before() { thisScript.myToast('脚本即将停止，正在上传数据'); } });
					thisScript.stop();
					sleep(3000);
					return;
				}
			}
		}
		if (thisScript.oper({
			name: '进入奉纳',
			operator: [thisOperator[15], thisOperator[16], thisOperator[17], thisOperator[18]
				, thisOperator[19]]
		})) {
			return true;
		}
		return false;
	}
}

