	operatorFunc(thisScript: Script, thisOperator: IFuncOperator[]): boolean {
		const thisConf = thisScript.scheme.config['319'];
		if (thisScript.oper({
			id: 319,
			name: '缘结趣游出现铃铛',
			operator: [thisOperator[9]]
		})) {
			return true;
		}
		if (thisScript.oper({
			id: 319,
			name: '缘结趣游不足十抽',
			operator: [{ desc: thisOperator[2].desc }]
		})) {
			if (thisConf.buy) {
				if (thisConf.over) {
					thisScript.regionClick([thisOperator[5].oper[0]]);
					thisScript.regionClick([thisOperator[5].oper[1]]);
				} else {
					thisScript.regionClick([thisOperator[5].oper[1]]);
				}
			} else {
				thisScript.regionClick([thisOperator[2].oper[0]]);
				thisScript.global.youjiequyuan_ten = false;
			}
			return true;
		}
		if (thisScript.oper({
			id: 319,
			name: '缘结趣游不足一抽',
			operator: [thisOperator[4]]
		})) {
			thisScript.myToast('缘结趣游不足一抽，脚本自动停止');
			thisScript.doPush(thisScript, { text: `[${thisScript.schemeHistory.map(item => item.schemeName).join('、')}]已停止，请查看。`, before() { thisScript.myToast('脚本即将停止，正在上传数据'); } });
			thisScript.stop();
			sleep(2000);
			return false;
		}
		if (thisScript.oper({
			id: 319,
			name: '缘结趣游抽足铃铛（黑蛋加成弹窗）',
			operator: [thisOperator[6]]
		})) {
			return true;
		}
		if (!thisConf.over && thisScript.oper({
			id: 319,
			name: '缘结趣游抽足铃铛',
			operator: [thisOperator[7]]
		})) {
			thisScript.myToast('缘结趣游抽足铃铛，脚本自动停止');
			thisScript.doPush(thisScript, { text: `[${thisScript.schemeHistory.map(item => item.schemeName).join('、')}]已停止，请查看。`, before() { thisScript.myToast('脚本即将停止，正在上传数据'); } });
			thisScript.stop();
			sleep(2000);
			return false;
		}
		if (thisScript.oper({
			id: 319,
			name: '缘结趣游界面',
			operator: [{ desc: thisOperator[0].desc }]
		})) {
			if (thisScript.global.youjiequyuan_ten) {
				thisScript.oper({
					id: 319,
					name: '勾选十连抽',
					operator: [thisOperator[1]]
				})
			} else {
				thisScript.oper({
					id: 319,
					name: '取消勾选十连抽',
					operator: [thisOperator[3]]
				})
			}
			thisScript.regionClick([thisOperator[0].oper[0]]);
			return true;
		}
		if (thisScript.oper({
			id: 319,
			name: '缘结趣游购买并抽完票',
			operator: [thisOperator[8]]
		})) {
			thisScript.global.youjiequyuan_ten = false;
		}
		return false;
	}
